function sheetDropcontactContacts({ rows }) {
  if (!Array.isArray(rows) || rows.length === 0)
    throw new Error("Expected the complete spreadsheet rows");
  if (rows.length > 250)
    throw new Error(
      "The source submits one enrichment batch; choose a range containing at most 250 contacts before running",
    );
  const fields = {
    email: "email",
    firstName: "first_name",
    lastName: "last_name",
    fullName: "full_name",
    companyName: "company",
    website: "website",
    LinkedIn: "linkedin",
  };
  const data = rows.map((row, index) => {
    if (!row || typeof row !== "object" || Array.isArray(row))
      throw new Error("Invalid spreadsheet contact at row " + (index + 2));
    const contact = {};
    for (const [column, field] of Object.entries(fields)) {
      const value = row[column];
      if (value === undefined || value === null || value === "") continue;
      if (typeof value !== "string")
        throw new Error("Contact column " + column + " must contain text at row " + (index + 2));
      if (value.trim()) contact[field] = value;
    }
    if (!(
      contact.email ||
      contact.linkedin ||
      ((contact.company || contact.website) &&
        ((contact.first_name && contact.last_name) || contact.full_name))
    ))
      throw new Error(
        "Contact row " + (index + 2) + " needs email, LinkedIn, or a name and company/website",
      );
    return contact;
  });
  return { data, count: data.length, hasContacts: data.length > 0 };
}

const rows = $input.all().map((item) => item.json);
if (!rows.length) return [];
const batch = sheetDropcontactContacts({ rows });
return batch.data.map((contact, index) => ({ json: contact, pairedItem: { item: index } }));

function dropcontactLeadPlans({ data, error, success, status, raw, count, campaignId }) {
  if (error !== false || success !== true || status !== "succeeded")
    throw new Error(
      "Dropcontact enrichment is not complete after the source wait; do not submit the batch again without checking its request ID",
    );
  if (!Array.isArray(data) || data.length !== count)
    throw new Error("Dropcontact did not return the complete contact batch");
  if (
    raw !== null &&
    raw !== undefined &&
    (!Array.isArray(raw.data) ||
      raw.data.length !== count ||
      raw.data.some((record) => !record || typeof record !== "object" || Array.isArray(record)))
  )
    throw new Error("Dropcontact returned an invalid or incomplete raw contact batch");
  if (typeof campaignId !== "string" || !campaignId.trim())
    throw new Error("Configure the Lemlist campaign ID");
  const campaignPath = encodeURIComponent(campaignId);
  const plans = data.map((record, index) => {
    if (
      !record ||
      typeof record !== "object" ||
      Array.isArray(record) ||
      !Array.isArray(record.email) ||
      !record.email.length ||
      typeof record.email[0]?.email !== "string" ||
      !record.email[0].email.trim()
    )
      throw new Error(
        "Contact " +
          (index + 1) +
          " has no first enriched email; no leads have been created by this step",
      );
    const email = record.email[0].email;
    const body = {};
    for (const [target, source] of [
      ["firstName", "first_name"],
      ["lastName", "last_name"],
      ["companyName", "company"],
    ]) {
      if (record[source] === undefined) continue;
      if (record[source] !== null && typeof record[source] !== "string")
        throw new Error("Invalid enriched field " + source + " at contact " + (index + 1));
      body[target] = record[source];
    }
    return {
      email,
      emailPath: encodeURIComponent(email),
      campaignPath,
      endpoint: "/campaigns/" + campaignPath + "/leads/" + encodeURIComponent(email),
      body,
    };
  });
  return { plans, enriched: data, count };
}

const data = $input.all().map((item) => item.json);
const count = $("Map the complete contact batch").all().length;
const result = dropcontactLeadPlans({
  data,
  error: false,
  success: true,
  status: "succeeded",
  raw: null,
  count,
  campaignId: "YOUR_LEMLIST_CAMPAIGN_ID",
});
return result.plans.map((plan, index) => ({ json: plan, pairedItem: { item: index } }));
